#include <stdio.h>

#define MAXS 205
#define MAXE 40005

static int head[MAXS];
static int nxt[MAXE];
static int to[MAXE];
static int A[MAXS];
static int dp[MAXS];
static unsigned char vis[MAXS];
static int ecnt = 0;

/* Como a formiga sempre escorrega para um salao de altura ESTRITAMENTE
   menor, qualquer movimento diminui a altura: o grafo de movimentos e um
   DAG e nenhum salao pode ser revisitado. O numero maximo de saloes
   visitados (excluindo o inicial) e o caminho mais longo saindo de P. */
static int dfs(int u) {
    if (vis[u]) return dp[u];
    vis[u] = 1;
    int best = 1; /* conta o proprio u */
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int c = dfs(to[e]) + 1;
        if (c > best) best = c;
    }
    return dp[u] = best;
}

int main(void) {
    int S, T, P;

    if (scanf("%d %d %d", &S, &T, &P) != 3) return 0;

    for (int i = 1; i <= S; i++) {
        if (scanf("%d", &A[i]) != 1) return 0;
    }

    for (int i = 1; i <= S; i++) head[i] = -1;

    for (int t = 0; t < T; t++) {
        int I, J;
        if (scanf("%d %d", &I, &J) != 2) return 0;
        /* O tunel {I,J} permite escorregar apenas do mais alto para o mais baixo.
           Alturas iguais: tunel inutil para escorregar. */
        if (A[I] > A[J]) {
            to[ecnt] = J; nxt[ecnt] = head[I]; head[I] = ecnt++;
        } else if (A[J] > A[I]) {
            to[ecnt] = I; nxt[ecnt] = head[J]; head[J] = ecnt++;
        }
    }

    /* dp[P] = maximo de saloes no caminho descendente (incluindo P);
       a resposta exclui P. */
    printf("%d\n", dfs(P) - 1);

    return 0;
}
